#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr putGradient ( FSSpec theMeshFSSpec );OSErr putGradient ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError, theError1, theError2;	unsigned char *theMapH, *theMapL;	int i, x, y;	long meshSize, meshWidth, meshHeight;	meshHeader theMeshHeader;	gridData *theGrid;	union gradientBytes	{		short	theShort;		char	theBytes[2];	} theGradient;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theMapL = (unsigned char *) NewPtr (meshSize);	if ( theMapL == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theMapH = (unsigned char *) NewPtr (meshSize);	if ( theMapH == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theError1 = readBMP( "\p:Graphics.in:gradientL.bmp", meshWidth, meshHeight, nil, (char *) theMapL );	theError2 = readBMP( "\p:Graphics.in:gradientH.bmp", meshWidth, meshHeight, nil, (char *) theMapH );	if ( theError1 != noErr || theError2 != noErr ){		DisposePtr ( (Ptr) theMapL );		DisposePtr ( (Ptr) theMapH );		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return theError;	}	// get the grid Z data into an array	for ( y = 0, i = 0; y < meshHeight * meshWidth; y += meshWidth ){		for ( x = meshWidth - 1; x >= 0; x--, i++ ){			theGradient.theBytes[0] = theMapL[x + y];			theGradient.theBytes[1] = theMapH[x + y];			theGrid[i].gradient = theGradient.theShort;		}	}	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theMapL );	DisposePtr ( (Ptr) theMapH );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );	return theError;}